<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('contacts.view');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT ct.*,c.company_name,c.country,u.name owner_name FROM contacts ct LEFT JOIN clients c ON c.id=ct.client_id LEFT JOIN users u ON u.id=ct.owner_user_id WHERE ct.id=?');$s->execute([$id]);$contact=$s->fetch();if(!$contact){http_response_code(404);exit('Contacto no encontrado.');}$pageTitle=trim($contact['first_name'].' '.$contact['last_name']);$a=db()->prepare('SELECT a.*,u.name user_name FROM activities a LEFT JOIN users u ON u.id=a.assigned_to WHERE a.contact_id=? ORDER BY COALESCE(a.due_at,a.created_at) DESC LIMIT 50');$a->execute([$id]);$activities=$a->fetchAll();$d=db()->prepare('SELECT d.*,ps.name_es stage_name,ps.color FROM deals d JOIN pipeline_stages ps ON ps.id=d.stage_id WHERE d.contact_id=? ORDER BY d.created_at DESC');$d->execute([$id]);$deals=$d->fetchAll();require __DIR__.'/includes/header.php';?>
<div class="module-tabs"><a href="contacts.php">Contactos</a><a class="active" href="#">Ficha individual</a><?php if(has_permission('activities.manage')):?><a href="activity_form.php?contact_id=<?=$id?>">+ Actividad</a><?php endif;?><?php if(has_permission('deals.manage')):?><a href="deal_form.php?contact_id=<?=$id?>&client_id=<?=(int)$contact['client_id']?>">+ Negocio</a><?php endif;?></div>
<section class="panel"><div class="panel-header"><div><h2><?=e($pageTitle)?></h2><span class="table-sub"><?=e($contact['job_title']?:'Sin cargo')?><?= $contact['company_name']?' · '.e($contact['company_name']):''?></span></div><div class="actions"><?php if($contact['email']):?><a class="btn btn-light btn-small" href="mailto:<?=e($contact['email'])?>">Enviar email</a><?php endif;?><?php if($contact['whatsapp']):?><a class="btn btn-success btn-small" target="_blank" rel="noopener" href="https://wa.me/<?=e(preg_replace('/\D+/','',$contact['whatsapp']))?>">WhatsApp</a><?php endif;?><?php if(has_permission('contacts.manage')):?><a class="btn btn-primary btn-small" href="contact_form.php?id=<?=$id?>">Editar</a><?php endif;?></div></div><div class="panel-body details-grid"><div class="detail"><small>Email</small><strong><?=e($contact['email']?:'—')?></strong></div><div class="detail"><small>Teléfono / WhatsApp</small><strong><?=e($contact['whatsapp']?:$contact['phone']?:'—')?></strong></div><div class="detail"><small>Empresa</small><strong><?php if($contact['client_id']):?><a href="client_view.php?id=<?=$contact['client_id']?>"><?=e($contact['company_name'])?></a><?php else:?>Independiente<?php endif;?></strong></div><div class="detail"><small>Responsable</small><strong><?=e($contact['owner_name']?:'Sin asignar')?></strong></div><div class="detail"><small>Idioma</small><strong><?=e(language_label($contact['language']))?></strong></div><div class="detail"><small>Origen</small><strong><?=e($contact['source']?:'—')?></strong></div><?php if($contact['notes']):?><div class="detail" style="grid-column:1/-1"><small>Notas</small><strong style="white-space:pre-wrap"><?=e($contact['notes'])?></strong></div><?php endif;?></div></section>
<div class="dashboard-grid" style="margin-top:18px"><section class="panel"><div class="panel-header"><h2>Línea de tiempo de actividades</h2><?php if(has_permission('activities.manage')):?><a class="btn btn-primary btn-small" href="activity_form.php?contact_id=<?=$id?>">+ ACTIVIDAD</a><?php endif;?></div><div class="panel-body activity-timeline"><?php if(!$activities):?><div class="empty">Todavía no hay llamadas, correos, reuniones o tareas.</div><?php endif;?><?php foreach($activities as$item):?><article class="activity-entry <?=$item['status']==='completed'?'completed':''?>"><div class="activity-entry-icon"><?=crm_icon($item['activity_type']==='meeting'?'calendar':($item['activity_type']==='email'?'mail':'activity'))?></div><div><h4><?=e($item['subject'])?></h4><span class="badge badge-<?=$item['status']==='completed'?'green':'orange'?>"><?=e(crm_activity_type_label($item['activity_type']))?> · <?=e($item['status'])?></span><?php if($item['details']):?><p><?=e($item['details'])?></p><?php endif;?></div><time><?=e($item['due_at']?(new DateTimeImmutable($item['due_at']))->format('d/m/Y H:i'):(new DateTimeImmutable($item['created_at']))->format('d/m/Y H:i'))?></time></article><?php endforeach;?></div></section><aside><section class="panel"><div class="panel-header"><h2>Negocios relacionados</h2></div><div class="panel-body"><?php if(!$deals):?><div class="empty">Sin oportunidades.</div><?php else:?><div class="metric-list"><?php foreach($deals as$deal):?><div class="metric-row"><span><a class="table-title" href="deal_view.php?id=<?=$deal['id']?>"><?=e($deal['title'])?></a><small class="table-sub"><?=e($deal['stage_name'])?></small></span><strong><?=e(format_money($deal['amount'],$deal['currency']))?></strong></div><?php endforeach;?></div><?php endif;?></div></section></aside></div>
